#!/usr/bin/env node
// Imports the shared rewind parity cases into test/fixtures/bedrock/rewind-parity.json.
//
//   node scripts/import-rewind-parity.js path/to/rewind-v1.json
//
// The cases are checked-in expectations for the Bedrock client's rewind ring and the packet
// handlers that file against it, written down from the client's behaviour and shared by several
// independent implementations, this engine's among them (test/bedrock/rewind-parity.test.js). They
// are not generated by any of them -- an expectation both sides compute is a tautology, not a test.
//
// Only the kinds this engine implements are copied: the file holds two thousand cases, most of them
// about mechanisms prismarine-physics has no counterpart for, and importing those would be shipping
// three megabytes to skip. KINDS below is the list, and it grows by a line as a mechanism is ported.
// The manifest records the WHOLE source file's digest and case count, so a stale subset is visible
// even when the kinds it took are unchanged.

const fs = require('fs')
const path = require('path')
const crypto = require('crypto')

// The kinds this engine answers for, each a mechanism under lib/bedrock/.
const KINDS = [
  'history', // the ring: push, queue, attach, mark, complete, clear, the window and the anchor
  'history-size', // the history size a server request is sanitized to
  'route', // the filing protocol: which frame a correction lands on, per route
  'spatial-correction', // what a position correction and a near teleport write
  'velocity-replay', // the velocity-only correction (set_entity_motion)
  'attribute', // how a modifier list folds into a value
  'attribute-update', // what an update_attributes packet does to the value the client holds
  'modifier', // the modifier one level of an effect contributes
  'cook-move-vector', // the direction bits or stick cooked into the move vector
  'sprint-intent', // whether the sprint starts or stops this tick
  'flight-intent', // the jump / change-height double tap that toggles flight
  'pose-clearance', // the room the box has to stand, sneak and crawl
  'liquid-surface', // the height of a liquid cell's surface, which the eye must be below to be under water
  'swim-amount', // the swim pose amount the jump reads
  'ground-flight', // the nudge that lifts a flyer off the ground
  'vertical-flight', // the hover damping and the up / down impulses
  'flying-speed', // the fly speed, doubled while sprinting
  'flying-drag', // the vertical drag while flying
  'flying-friction', // the horizontal friction while flying, through the hover's override
  'berry-slowdown', // the sweet berry bush's multiplier, folded lane by lane
  'block-slowdown', // the slowdown multiplier on the requested move
  'water-sink-input', // the 0.04 sink of a player that wants down in water
  'sprint-permission', // riding, allowed to sprint, limited by hunger
  'move-speed-cap' // a request beyond 500, or of an immobile player, is zeroed
]

function main (source) {
  if (!source || !fs.existsSync(source)) {
    console.error(`no parity file at ${source}\nusage: node scripts/import-rewind-parity.js path/to/rewind-v1.json`)
    process.exit(1)
  }
  const raw = fs.readFileSync(source)
  const parsed = JSON.parse(raw.toString('utf8'))
  if (parsed.schemaVersion !== 1) throw new Error(`unexpected schemaVersion ${parsed.schemaVersion}`)

  const taken = KINDS.map(kind => {
    const cases = parsed.cases.filter(one => one.kind === kind)
    if (!cases.length) throw new Error(`the source carries no "${kind}" case: the kind was renamed or dropped`)
    return cases
  }).flat()

  const out = path.join(__dirname, '..', 'test', 'fixtures', 'bedrock')
  fs.writeFileSync(path.join(out, 'rewind-parity.json'),
    JSON.stringify({ schemaVersion: 1, kinds: KINDS, cases: taken }, null, 1) + '\n')
  fs.writeFileSync(path.join(out, 'rewind-parity-manifest.json'), JSON.stringify({
    source: path.basename(source),
    sourceSha256: crypto.createHash('sha256').update(raw).digest('hex'),
    sourceCases: parsed.cases.length,
    kinds: KINDS,
    cases: taken.length,
    imported: new Date().toISOString().slice(0, 10)
  }, null, 2) + '\n')
  console.log(`imported ${taken.length} cases of ${parsed.cases.length} (${KINDS.join(', ')})`)
}

main(process.argv[2])
